package com.investory.auth.infra.security;

// 테스트 전용 RSA 2048비트 키쌍 두 개(PKCS8/X509 DER, base64) — 운영 키가 아니다.
// KEY_A/KEY_B는 서로 다른 키쌍이라 "다른 키로 서명된 토큰은 검증에 실패한다" 같은 테스트에 쓴다.
//
// 생성 방법 (openssl 3.0 기준 — genpkey -outform DER의 기본 산출물은 PKCS1이라 pkcs8 변환이
// 반드시 필요하다. 이 단계를 빼먹으면 KeyFactory.generatePrivate()가
// "algid parse error, not a sequence"로 실패한다):
//   openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -outform DER -out raw.der
//   openssl pkcs8 -topk8 -nocrypt -in raw.der -inform DER -outform DER -out private.der
//   openssl rsa -in raw.der -inform DER -pubout -outform DER -out public.der
//   base64 -i private.der | tr -d '\n'
//   base64 -i public.der | tr -d '\n'
public class RsaTestKeys {

    public static final String PRIVATE_KEY_A = "";
    public static final String PUBLIC_KEY_A = "";

    public static final String PRIVATE_KEY_B = "";
    public static final String PUBLIC_KEY_B = "";

    private RsaTestKeys() {
    }
}
